/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */

struct Info {
    int depth;
    int parent;
};

void dfs(struct TreeNode* root, int x, int y, int depth, int parent, struct Info* xInfo, struct Info* yInfo) {
    if (!root) return;
    if (root->val == x) {
        xInfo->depth = depth;
        xInfo->parent = parent;
    }
    if (root->val == y) {
        yInfo->depth = depth;
        yInfo->parent = parent;
    }
    dfs(root->left, x, y, depth + 1, root->val, xInfo, yInfo);
    dfs(root->right, x, y, depth + 1, root->val, xInfo, yInfo);
}

bool isCousins(struct TreeNode* root, int x, int y){
    struct Info xInfo = {-1, -1};
    struct Info yInfo = {-1, -1};
    dfs(root, x, y, 0, -1, &xInfo, &yInfo);
    return (xInfo.depth == yInfo.depth) && (xInfo.parent != yInfo.parent);
}

